import React, { useEffect, useState } from "react";

// Badge data extracted from BadgesPage.js for local point calculation
const BADGE_DEFINITIONS = [
  {
    title: "Bronze Volunteer",
    desc: "Earned after 20 volunteer points",
    icon: "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105",
    pointsThreshold: 20,
  },
  {
    title: "Silver Volunteer",
    desc: "Earned after 50 volunteer points",
    icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
    pointsThreshold: 50,
  },
  {
    title: "Gold Volunteer",
    desc: "Earned after 100 volunteer points",
    icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
    pointsThreshold: 100,
  },
  {
    title: "Silver Donor",
    desc: "Earned after 50 donor points", // Assuming total points include donor points
    icon: "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
    pointsThreshold: 50,
  },
  {
    title: "Gold Donor",
    desc: "Earned after 100 donor points", // Assuming total points include donor points
    icon: "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
    pointsThreshold: 100,
  },
  {
    title: "Platinum Donor",
    desc: "Earned after 200 donor points", // Assuming total points include donor points
    icon: "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180",
    pointsThreshold: 200,
  },
];

// Helper function to calculate earned badges based on points
function getBadgesFromPoints(points) {
  return BADGE_DEFINITIONS.filter((badge) => points >= badge.pointsThreshold).map(
    (b) => ({
      title: b.title,
      description: b.desc,
      icon: b.icon,
      badge_key: b.title.replace(/\s/g, ""), // Use title for key
    })
  );
}

export default function AchievementsPanel({
  token,
  me = {},
  role = "user",
  onViewNgo,
  setMsg,
  achievements: propAchievements, // Accept achievements passed from parent
}) {
  const [achievements, setAchievements] = useState(
    propAchievements || null
  );
  const [badges, setBadges] = useState(propAchievements?.badges || []);

  useEffect(() => {
    const userPoints = me.points || 0;
    
    // PRIORITY 1: Use badges passed from the parent component (which typically handles point calculation)
    if (propAchievements) {
      setAchievements(propAchievements);
      setBadges(propAchievements.badges || []);
      return;
    }
    
    // PRIORITY 2: Fallback/Initial load - Use the client-side points logic if no token or API fails
    const calculatedBadges = getBadgesFromPoints(userPoints);
    setBadges(calculatedBadges);
    setAchievements({ badges: calculatedBadges }); // Set achievements to mark as loaded

    if (!token) return;

    // PRIORITY 3: Fetch from API to get potentially server-side assigned badges
    const apiBase = process.env.REACT_APP_API || "http://localhost:4000";
    const achievementUrl =
      role === "NGO"
        ? `${apiBase}/api/ngo/achievements`
        : `${apiBase}/api/actions/achievements`;
    const userBadgesUrl = `${apiBase}/api/actions/user-badges`;

    // Fetch and merge any server-side badges with the calculated ones (which use current points)
    Promise.allSettled([
      fetch(achievementUrl, {
        headers: { Authorization: `Bearer ${token}` },
      }).then((r) => (r.ok ? r.json() : { badges: [] })),
      fetch(userBadgesUrl, {
        headers: { Authorization: `Bearer ${token}` },
      }).then((r) => (r.ok ? r.json() : { badges: [] })),
    ])
      .then((results) => {
        const serverBadges = [];
        results.forEach((result) => {
          if (
            result.status === "fulfilled" &&
            result.value &&
            result.value.badges
          ) {
            serverBadges.push(...result.value.badges);
          }
        });

        // Combine all badge sources (Calculated, server achievements, server user-badges)
        const allBadges = [...calculatedBadges, ...serverBadges];

        // Deduplicate using badge title/key (ensuring client-side logic doesn't override server)
        const uniqueBadgesMap = {};
        allBadges.forEach((badge) => {
          const key = badge.title || badge.badge_key || badge.id;
          if (key) {
            // Keep the server version if keys clash, or the first one found
            if (!uniqueBadgesMap[key]) {
              uniqueBadgesMap[key] = badge;
            }
          }
        });

        const finalBadges = Object.values(uniqueBadgesMap);
        setBadges(finalBadges);
        setAchievements({ badges: finalBadges }); // Final state reflects all loaded badges
      })
      .catch((err) => {
        console.error("Achievements load error", err);
        // Fallback to client-side calculated badges if API fails
        setBadges(calculatedBadges);
        setAchievements({ badges: calculatedBadges });
      });
  }, [token, role, propAchievements, me.points]);

  return (
    <div style={{ width: 320, flexShrink: 0 }}>
      <h3 style={{ marginBottom: 12 }}>Achievements</h3>

      <div
        style={{
          background: "linear-gradient(135deg,#0ea5e9,#6366f1)",
          padding: 18,
          borderRadius: 12,
          color: "#fff",
          textAlign: "center",
          boxShadow: "0 8px 30px rgba(2,6,23,0.08)",
        }}
      >
        <div style={{ fontSize: 42, fontWeight: 800 }}>
          {me?.points || 0}
        </div>
        <div style={{ opacity: 0.9, marginTop: 6 }}>POINTS</div>
      </div>

      <div style={{ marginTop: 14 }}>
        <h4 style={{ marginBottom: 8 }}>Badges</h4>

        {!achievements && (
          <div style={{ fontSize: 13, color: "#666" }}>Loading badges...</div>
        )}

        {achievements && badges.length === 0 && (
          <div
            style={{
              padding: 14,
              borderRadius: 10,
              background: "#fff",
              color: "#666",
              boxShadow: "0 6px 20px rgba(0,0,0,0.04)",
            }}
          >
            No badges yet — participate to earn rewards.
          </div>
        )}

        {badges.length > 0 && (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(2,1fr)",
              gap: 10,
              marginTop: 10,
            }}
          >
            {badges.map((b, i) => {
              // Default icon mapping (uses the local badge definitions for consistency)
              const localBadge = BADGE_DEFINITIONS.find(
                (def) => def.title === b.title || def.title === b.badge_key
              );

              const finalIcon =
                b.icon || localBadge?.icon || "";

              return (
                <div
                  key={b.badge_key || b.key || i}
                  style={{
                    background: "#fff",
                    padding: 10,
                    borderRadius: 10,
                    boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
                    border: "1px solid #f1f5f9",
                    textAlign: "center",
                  }}
                >
                  {finalIcon && (
                    <img
                      src={finalIcon}
                      alt={b.title}
                      style={{
                        width: 45,
                        height: 45,
                        marginBottom: 6,
                        objectFit: "contain",
                      }}
                    />
                  )}

                  <div style={{ fontWeight: 700, fontSize: 14 }}>
                    {b.title || b.badge_key}
                  </div>

                  <div style={{ fontSize: 12, color: "#555" }}>
                    {b.description || b.desc}
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {onViewNgo && (
        <div style={{ marginTop: 18 }}>
          <button
            onClick={() => onViewNgo()}
            style={{
              width: "100%",
              padding: "10px 12px",
              borderRadius: 10,
              background: "#2563eb",
              color: "#fff",
              border: 0,
              cursor: "pointer",
            }}
          >
            View Hosting NGOs
          </button>
        </div>
      )}
    </div>
  );
}
